CREATE VIEW v_totals AS
SELECT dept, SUM(base_salary) AS cost
FROM employees GROUP BY dept;
SELECT * FROM v_totals ORDER BY dept;

CREATE VIEW v_high_paid AS
SELECT name, base_salary FROM employees
WHERE base_salary > 90000;
SELECT COUNT(*) AS n FROM v_high_paid;

UPDATE employees SET bonus = 5000 WHERE base_salary >= 90000;
UPDATE employees SET bonus = 2000 WHERE base_salary < 90000;
SELECT DISTINCT bonus FROM employees;

CREATE PROCEDURE add_bonus (IN emp_id INT, IN amt INT)
BEGIN
  UPDATE employees SET bonus = bonus + amt
  WHERE id = emp_id;
END;

UPDATE employees SET bonus = (base_salary / 100) * 5
WHERE dept = 'Engineering';
UPDATE employees SET bonus = 4000
WHERE dept = 'Engineering' AND bonus > 4000;
SELECT name, bonus FROM employees
WHERE dept = 'Engineering';
